import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static final byte[] tok = new byte[64];

    // Reads one whitespace-separated token into a String (ASCII, so ISO-8859-1 is exact).
    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        int len = 0;
        while (c > ' ') {
            tok[len++] = (byte) c;
            c = readByte();
        }
        return new String(tok, 0, len, StandardCharsets.ISO_8859_1);
    }

    public static void main(String[] args) throws IOException {
        int q = Integer.parseInt(next());
        HashMap<String, Integer> id = new HashMap<>(q * 2);
        ArrayList<String> order = new ArrayList<>();
        int[] cnt = new int[16];
        int p = 0; // every ip numbered below p has appeared at least twice
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = next();
            if (cmd.charAt(0) == 'A') {
                String ip = next();
                Integer k = id.get(ip);
                if (k == null) {
                    k = order.size();
                    id.put(ip, k);
                    order.add(ip);
                    if (k == cnt.length) cnt = Arrays.copyOf(cnt, k * 2);
                }
                cnt[k]++;
            } else {
                while (p < order.size() && cnt[p] >= 2) p++;
                if (p < order.size()) out.append(order.get(p));
                out.append('\n');
            }
        }
        System.out.write(out.toString().getBytes(StandardCharsets.ISO_8859_1));
        System.out.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	tok := make([]byte, 0, 64)
	next := func() []byte {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		tok = tok[:0]
		for err == nil && c > ' ' {
			tok = append(tok, c)
			c, err = reader.ReadByte()
		}
		return tok
	}
	q, _ := strconv.Atoi(string(next()))
	id := make(map[string]int, q)
	var order []string
	var cnt []int32
	p := 0 // every ip numbered below p has appeared at least twice
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i := 0; i < q; i++ {
		if cmd := next(); cmd[0] == 'A' {
			ip := next()
			k, ok := id[string(ip)]
			if !ok {
				k = len(order)
				s := string(ip)
				id[s] = k
				order = append(order, s)
				cnt = append(cnt, 0)
			}
			cnt[k]++
		} else {
			for p < len(order) && cnt[p] >= 2 {
				p++
			}
			if p < len(order) {
				w.WriteString(order[p])
			}
			w.WriteByte('\n')
		}
	}
}
